        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));comp=[];col=g[r][c]
                while st:
                    y,x=st.pop();comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<H and 0<=b<W and g[a][b]==col and (a,b) not in seen:
                            seen.add((a,b));st.append((a,b))
                out.append((col,sorted(comp)))
